    # Vulnerability: Tool executes a highly destructive action automatically without a human-in-the-loop confirmation
    if response.choices[0].message.tool_calls:
        for tool_call in response.choices[0].message.tool_calls:
            if tool_call.function.name == "delete_repository":
                args = json.loads(tool_call.function.arguments)
                delete_repository(args.get("repo_name"))

