const SYSTEM_PROMPT = `You are the virtual assistant for Northwind Bank.
Ask a clarifying question when the request is unclear.
Use a friendly, professional tone.
Never make promises about delivery dates.
Keep answers short and polite.`;

const app = express();
app.use(express.json());

app.post("/chat", async (req, res) => {
  const query: string = req.body.message;
  console.info("chat request received");
  if (!query || query.length > 2000) throw new Error("invalid message");
  const prompt = `${SYSTEM_PROMPT}\n\nUser: ${query}`;
  const completion = await client.chat.completions.create(
    {
      model: "gpt-4o",
      messages: [
        { role: "user", content: prompt },
      ],
      max_tokens: 400,
    },
    { timeout: 30000 },
  );
  const reply = completion.choices[0].message.content ?? "";
  const payload = { reply };
  res.json(payload);
});

