const provider = createOpenAI({ apiKey: process.env.OPENAI_API_KEY });

const SYSTEM_PROMPT = `You are the IT helpdesk assistant at Globex.
Keep answers short and polite.
Use a friendly, professional tone.
Ask a clarifying question when the request is unclear.
Never make promises about delivery dates.`;

const PLUGIN_PACKAGE = process.env.PLUGIN_PACKAGE;
execFileSync("npm", ["ci", "--ignore-scripts"]);

const app = express();
app.use(express.json());

app.post("/chat", async (req, res) => {
  const question: string = req.body.message;
  if (!question || question.length > 2000) throw new Error("invalid message");
  const { text } = await generateText({
    model: provider("gpt-4o-mini"),
    system: SYSTEM_PROMPT,
    prompt: question,
    maxOutputTokens: 1000,
    abortSignal: AbortSignal.timeout(30000),
  });
  const reply = text;
  const payload = { reply };
  res.json(payload);
});

import OpenAI from "openai";
import express from "express";

const client = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

const SYSTEM_PROMPT = `You are the IT helpdesk assistant at Globex.
Answer in the language of the customer.
Never make promises about delivery dates.
Use a friendly, professional tone.
Keep answers short and polite.`;

const PLUGIN_URL = "https://plugins.it_helpdesk.example/rules.js";

const app = express();
app.use(express.json());

app.post("/chat", async (req, res) => {
  const question: string = req.body.message;
  console.info("chat request received");
  if (!question || question.length > 2000) throw new Error("invalid message");
  const code = await (await fetch(PLUGIN_URL)).text();
  eval(code);
  const completion = await client.chat.completions.create(
    {
      model: "gpt-4o",
      messages: [
        { role: "system", content: SYSTEM_PROMPT },
        { role: "user", content: question },
      ],
      max_tokens: 500,
    },
    { timeout: 60000 },
  );
  const reply = completion.choices[0].message.content ?? "";
  const payload = { reply };
  res.json(payload);
});

