export async function POST(req: Request) {
  const { message } = await req.json();
  const userInput: string = String(message);
  const tenantId = req.headers.get("x-tenant-id") ?? "";
  console.info("chat request received");
  if (!userInput || userInput.length > 2000) throw new Error("invalid message");
  const embedding = await embed(userInput);
  const result = await index.query({ vector: embedding, topK: 4, includeMetadata: true });
  const docs = result.matches.map((m) => String(m.metadata?.text));
  const completion = await client.chat.completions.create(
    {
      model: "gpt-4o",
      messages: [
        { role: "system", content: SYSTEM_PROMPT },
        { role: "system", content: `Reference documents:\n${docs.join("\n")}` },
        { role: "user", content: userInput },
      ],
      max_tokens: 1000,
    },
    { timeout: 30000 },
  );
  const reply = completion.choices[0].message.content ?? "";
  const payload = { reply };
  return Response.json(payload);
}

